import { AppbarContainer, AppShell } from '@app/ui';
import { useTranslation } from '@fanfanlo';
import { AddWindowContent } from '@src/components/android-float/window/AddWindowContent';
export default function AndroidFloatWindow() {
  const { t } = useTranslation('homepage/pages/android-float-window/content');
  return (
    <AppShell>
      <AppbarContainer appbarProps={{ title: t('content.title'), back: true }}>
        <AddWindowContent />
      </AppbarContainer>
    </AppShell>
  );
}
