import { useState, useEffect } from "react";
import { useRouter } from "next/router";
import { WindowConf, createWindowConfCopy } from "@droid/android";
import { androidFloatWindowData } from "./data";
import { QuickCreateForm } from "./QuickCreateForm";
import { WindowConfEditor } from "./WindowConfEditor";

export function AddWindowContent(){
  const router = useRouter()

  // 模式状态: 'create' | 'edit'
  const [mode, setMode] = useState<'create' | 'edit'>('create');

  // 当前编辑的配置
  const [currentConf, setCurrentConf] = useState<WindowConf | null>(null);

  useEffect(()=>{
    console.log('AddWindowContent: init');
    androidFloatWindowData.init();
  }, [])

  /**
   * 快速创建完成 - 添加到列表并返回
   */
  const handleQuickCreate = (conf: WindowConf) => {
    console.log('AddWindowContent: handleQuickCreate, adding window config:', conf.tag);
    androidFloatWindowData.data.windowData.windowList.push(conf);
    router.back();
  };

  /**
   * 详细编辑 - 切换到编辑模式(不提前保存)
   */
  const handleDetailedEdit = (conf: WindowConf) => {
    console.log('AddWindowContent: handleDetailedEdit, switching to edit mode:', conf.tag);

    // 不要提前添加到列表! 只有用户点击"确认修改"时才保存
    // 使用 createWindowConfCopy 补齐所有默认属性
    const mergedConf = createWindowConfCopy(conf);
    console.log('AddWindowContent: merged config with defaults:', mergedConf);
    setCurrentConf(mergedConf);

    // 切换到编辑模式
    setMode('edit');
  };

  /**
   * 快速创建取消
   */
  const handleCancel = () => {
    console.log('AddWindowContent: handleCancel');
    router.back();
  };

  // 渲染不同模式
  if (mode === 'edit' && currentConf) {
    return <WindowConfEditor windowConf={currentConf} isCreateMode={true} />;
  }

  return (
    <QuickCreateForm
      onQuickCreate={handleQuickCreate}
      onDetailedEdit={handleDetailedEdit}
      onCancel={handleCancel}
    />
  )
}